import{_ as o,o as t,c as d,a3 as c}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Tenant API v1 — Documents","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Documents | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-documents"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Documents | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-documents"}]]},"headers":[],"relativePath":"api/tenant-v1-documents.md","filePath":"api/tenant-v1-documents.md","lastUpdated":1787438330000}'),a={name:"api/tenant-v1-documents.md"};function r(s,e,n,i,l,u){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="tenant-api-v1-—-documents" tabindex="-1">Tenant API v1 — Documents <a class="header-anchor" href="#tenant-api-v1-—-documents" aria-label="Permalink to &quot;Tenant API v1 — Documents&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:documents</code>, plus permission middleware / policies.</p><p>Workspace must also be entitled to <strong>Storage</strong>. Uploads enforce Storage quota via <code>WorkspaceStorageService::assertCanStore</code>.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-documents-stats" tabindex="-1">GET <code>/documents/stats</code> <a class="header-anchor" href="#get-documents-stats" aria-label="Permalink to &quot;GET `/documents/stats`&quot;">​</a></h3><p>Permission: <code>documents.view</code></p><p>Same filters as list (minus pagination/sort). Payload:</p><p><code>total</code>, <code>categorized</code>, <code>uncategorized</code>.</p><h2 id="documents-crud" tabindex="-1">Documents CRUD <a class="header-anchor" href="#documents-crud" aria-label="Permalink to &quot;Documents CRUD&quot;">​</a></h2><h3 id="get-documents" tabindex="-1">GET <code>/documents</code> <a class="header-anchor" href="#get-documents" aria-label="Permalink to &quot;GET `/documents`&quot;">​</a></h3><p>Permission: <code>documents.view</code></p><p>Query: <code>search</code> (title, description, original_name), <code>category_id</code>, <code>trashed</code> (<code>only</code> | <code>true</code> | <code>with</code>), <code>sort</code> (<code>title</code> | <code>original_name</code> | <code>size_bytes</code> | <code>created_at</code> | <code>updated_at</code>, default <code>created_at</code>), <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include nested <code>category</code> / <code>creator</code> when loaded, plus <code>original_name</code>, <code>mime</code>, <code>size_bytes</code>.</p><h3 id="post-documents" tabindex="-1">POST <code>/documents</code> <a class="header-anchor" href="#post-documents" aria-label="Permalink to &quot;POST `/documents`&quot;">​</a></h3><p>Permission: <code>documents.create</code></p><p><code>multipart/form-data</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>title</code></td><td>required, string, max 255</td></tr><tr><td><code>description</code></td><td>optional string, max 5000</td></tr><tr><td><code>category_id</code></td><td>optional; must exist in tenant <code>document_categories</code> and not soft-deleted</td></tr><tr><td><code>file</code></td><td>required file, max <strong>51200</strong> KB (50 MB); mimes: <code>pdf,doc,docx,xls,xlsx,ppt,pptx,txt,csv,rtf,odt,ods,odp,jpg,jpeg,png,gif,webp,zip,rar,7z</code></td></tr></tbody></table><p>Stores under the tenant Documents directory on the uploads disk. Counts toward Storage used bytes.</p><h3 id="get-documents-id" tabindex="-1">GET <code>/documents/{id}</code> <a class="header-anchor" href="#get-documents-id" aria-label="Permalink to &quot;GET `/documents/{id}`&quot;">​</a></h3><p>Permission: <code>documents.view</code>. Soft-deleted rows return not found on show.</p><p>Includes category and creator when loaded. Does <strong>not</strong> expose <code>path</code> / <code>disk</code>.</p><h3 id="put-documents-id" tabindex="-1">PUT <code>/documents/{id}</code> <a class="header-anchor" href="#put-documents-id" aria-label="Permalink to &quot;PUT `/documents/{id}`&quot;">​</a></h3><p>Permission: <code>documents.update</code></p><p>JSON body (partial): <code>title</code>, <code>description</code>, <code>category_id</code>. Prefer this for metadata-only updates.</p><h3 id="post-documents-id" tabindex="-1">POST <code>/documents/{id}</code> <a class="header-anchor" href="#post-documents-id" aria-label="Permalink to &quot;POST `/documents/{id}`&quot;">​</a></h3><p>Permission: <code>documents.update</code> (named route <code>documents.update.post</code>)</p><p><code>multipart/form-data</code> (partial): <code>title</code>, <code>description</code>, <code>category_id</code>, optional <code>file</code> (same mime/size rules as create). Replacing a larger file checks quota on the positive size delta only.</p><p><strong>File replace:</strong> use this <code>POST</code> twin — PHP does not populate uploaded files on a true HTTP <code>PUT</code>. The official SPA posts FormData here (no <code>_method</code> spoofing required). Method-spoofed <code>POST</code> + <code>_method=PUT</code> also works.</p><h3 id="post-documents-bulk-delete" tabindex="-1">POST <code>/documents/bulk-delete</code> <a class="header-anchor" href="#post-documents-bulk-delete" aria-label="Permalink to &quot;POST `/documents/bulk-delete`&quot;">​</a></h3><p>Permission: <code>documents.delete</code></p><p>Body: <code>{ &quot;ids&quot;: [1, 2, …] }</code> — required array, 1–100 distinct positive integers.</p><p>Soft-deletes active documents the actor is allowed to delete (uploader or workspace owner). Already-trashed / missing / unauthorized ids are listed under <code>failed</code>. Response data: <code>processed</code> (int), <code>failed</code> (<code>[{ id, message }]</code>). Returns <code>422</code> when <code>processed === 0</code>.</p><h3 id="post-documents-bulk-force-delete" tabindex="-1">POST <code>/documents/bulk-force-delete</code> <a class="header-anchor" href="#post-documents-bulk-force-delete" aria-label="Permalink to &quot;POST `/documents/bulk-force-delete`&quot;">​</a></h3><p>Permission: <code>documents.force.delete</code></p><p>Body: same <code>ids</code> shape as bulk-delete.</p><p>Permanently deletes <strong>soft-deleted</strong> documents the actor is allowed to force-delete (uploader or workspace owner) and removes objects from storage. Active documents are reported in <code>failed</code> (must soft-delete first). Returns <code>422</code> when <code>processed === 0</code>.</p><h3 id="delete-documents-id" tabindex="-1">DELETE <code>/documents/{id}</code> <a class="header-anchor" href="#delete-documents-id" aria-label="Permalink to &quot;DELETE `/documents/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>documents.delete</code>, and the actor must be the <strong>uploader</strong> (<code>created_by</code>) or the <strong>workspace owner</strong>. Soft-deleted bytes stop counting toward Storage used. Objects remain on disk until force delete or workspace trash retention purge (<code>trash:purge-expired</code>). Already-trashed rows return not found.</p><h3 id="post-documents-id-restore" tabindex="-1">POST <code>/documents/{id}/restore</code> <a class="header-anchor" href="#post-documents-id-restore" aria-label="Permalink to &quot;POST `/documents/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted document. Permission: <code>documents.restore</code>. Re-checks Storage quota for the document&#39;s <code>size_bytes</code> (soft-deleted rows are excluded from used bytes until restored). Returns <code>422</code> with <code>STORAGE_QUOTA_EXCEEDED</code> when restore would exceed allowance.</p><h3 id="delete-documents-id-force" tabindex="-1">DELETE <code>/documents/{id}/force</code> <a class="header-anchor" href="#delete-documents-id-force" aria-label="Permalink to &quot;DELETE `/documents/{id}/force`&quot;">​</a></h3><p>Permanently delete a <strong>soft-deleted</strong> document and remove the object from storage. Permission: <code>documents.force.delete</code>, and the actor must be the <strong>uploader</strong> or the <strong>workspace owner</strong>. Active documents return <code>400</code> (must soft-delete first).</p><h3 id="get-documents-id-download" tabindex="-1">GET <code>/documents/{id}/download</code> <a class="header-anchor" href="#get-documents-id-download" aria-label="Permalink to &quot;GET `/documents/{id}/download`&quot;">​</a></h3><p>Permission: <code>documents.view</code> (policy <code>download</code>). Streams the original file (<code>Content-Disposition</code> attachment using <code>original_name</code>). Soft-deleted or missing objects → 404.</p><h2 id="document-categories" tabindex="-1">Document categories <a class="header-anchor" href="#document-categories" aria-label="Permalink to &quot;Document categories&quot;">​</a></h2><h3 id="get-document-categories" tabindex="-1">GET <code>/document-categories</code> <a class="header-anchor" href="#get-document-categories" aria-label="Permalink to &quot;GET `/document-categories`&quot;">​</a></h3><p>Permission: <code>documents.view</code></p><p>Paginated list ordered by <code>sort_order</code>, then <code>name</code>.</p><h3 id="post-document-categories" tabindex="-1">POST <code>/document-categories</code> <a class="header-anchor" href="#post-document-categories" aria-label="Permalink to &quot;POST `/document-categories`&quot;">​</a></h3><p>Permission: <code>documents.create</code></p><p>Body:</p><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>name</code></td><td>required, string, max 255</td></tr><tr><td><code>slug</code></td><td>optional; unique per tenant; defaults to <code>Str::slug(name)</code></td></tr><tr><td><code>sort_order</code></td><td>optional integer (default 0)</td></tr><tr><td><code>is_active</code></td><td>optional boolean (default true)</td></tr></tbody></table><h3 id="get-document-categories-id" tabindex="-1">GET <code>/document-categories/{id}</code> <a class="header-anchor" href="#get-document-categories-id" aria-label="Permalink to &quot;GET `/document-categories/{id}`&quot;">​</a></h3><p>Permission: <code>documents.view</code></p><h3 id="put-document-categories-id" tabindex="-1">PUT <code>/document-categories/{id}</code> <a class="header-anchor" href="#put-document-categories-id" aria-label="Permalink to &quot;PUT `/document-categories/{id}`&quot;">​</a></h3><p>Permission: <code>documents.update</code></p><p>Partial update of <code>name</code>, <code>slug</code>, <code>sort_order</code>, <code>is_active</code>. Changing <code>name</code> without <code>slug</code> regenerates the slug.</p><h3 id="delete-document-categories-id" tabindex="-1">DELETE <code>/document-categories/{id}</code> <a class="header-anchor" href="#delete-document-categories-id" aria-label="Permalink to &quot;DELETE `/document-categories/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>documents.delete</code>. Fails with 422 if the category still has documents.</p><h3 id="post-document-categories-id-restore" tabindex="-1">POST <code>/document-categories/{id}/restore</code> <a class="header-anchor" href="#post-document-categories-id-restore" aria-label="Permalink to &quot;POST `/document-categories/{id}/restore`&quot;">​</a></h3><p>Permission: <code>documents.restore</code></p><h3 id="delete-document-categories-id-force" tabindex="-1">DELETE <code>/document-categories/{id}/force</code> <a class="header-anchor" href="#delete-document-categories-id-force" aria-label="Permalink to &quot;DELETE `/document-categories/{id}/force`&quot;">​</a></h3><p>Permanent delete. Permission: <code>documents.force.delete</code>. Fails with 422 if any documents (including soft-deleted) still reference the category.</p>',64)])])}const h=o(a,[["render",r]]);export{p as __pageData,h as default};
